235	// validateLineText 在 JSON 解析之前强制整行文本合法：原始字节必须是合法
236	// UTF-8，字符串内的 Unicode 转义必须表示有效字符。编码层/JSON 解析器会把
237	// 非法字节或未配对代理项静默替换成 U+FFFD，使损坏文本混入合法序列（被误判为
238	// 重复、冲突或错误命中查询），因此这里一律拒绝而不是修补后继续。
239	//
240	// 逐字节扫描、只在字符串内部识别转义：跳过词法空白与全部非字符串 token。
241	// 被转义的反斜杠（\\）后的 "uXXXX" 只是普通文本，不会被当成 Unicode 转义。
242	func validateLineText(line string) *LineError {
243		if !utf8.ValidString(line) {
244			return &LineError{Status: "error", Error: "invalid JSON: input is not valid UTF-8 text"}
245		}
246		inString := false
247		for i := 0; i < len(line); i++ {
248			c := line[i]
249			if !inString {
250				if c == '"' {
251					inString = true
252				}
253				continue
254			}
255			switch c {
256			case '"':
257				inString = false
258			case '\\':
259				if i+1 >= len(line) {
260					break // 悬空反斜杠：交给 JSON 解析器报错
261				}
262				if line[i+1] != 'u' {
263					i++ // 单字符转义（\\、\"、\n 等），跳过被转义字符
264					continue
265				}
266				// i 指向 '\'，i+1 指向 'u'；转义占据 i..i+5。
267				r, size := decodeJSONHexEscape(line, i+1)
268				if size == 0 {
269					return &LineError{Status: "error", Error: "invalid JSON: invalid Unicode escape sequence"}
270				}
271				if !utf16.IsSurrogate(r) {
272					i += 5
273					continue
274				}
275				if r >= 0xDC00 {
276					// 单独出现的低代理项。
277					return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
278				}
279				// 高代理项后必须紧接另一个表示低代理项的 \uXXXX 转义。
280				loPos := i + 6 // 第一个转义之后的字符位置
281				if loPos+1 >= len(line) || line[loPos] != '\\' || line[loPos+1] != 'u' {
282					return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
283				}
284				lo, loSize := decodeJSONHexEscape(line, loPos+1)
285				if loSize == 0 || lo < 0xDC00 || lo > 0xDFFF {
286					return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
287				}
288				i = loPos + loSize // 跳到第二转义的最后一个十六进制位，循环自增后越出
289			}
290		}
291		return nil
292	}
293	
294	// decodeJSONHexEscape 解析 line[pos:] 处的 "uXXXX"（pos 指向 'u'），
295	// 返回其码元与占用字节数（固定为 5）；不足四个十六进制数字时 size 为 0。
296	func decodeJSONHexEscape(line string, pos int) (rune, int) {
297		if pos+4 >= len(line) {
298			return 0, 0
299		}
300		var v rune
301		for j := pos + 1; j <= pos+4; j++ {
302			c := line[j]
303			var d rune
304			switch {
305			case c >= '0' && c <= '9':
306				d = rune(c - '0')
307			case c >= 'a' && c <= 'f':
308				d = rune(c-'a') + 10
309			case c >= 'A' && c <= 'F':
310				d = rune(c-'A') + 10
311			default:
312				return 0, 0
313			}
314			v = v<<4 | d
315		}
316		return v, 5
317	}
318	
319	// decodeTopValue 解析单行中唯一的 JSON 值并返回其原始内容与首个非空白字节
320	// （'[' 或 '{'）。整个值无法解析、为空或存在尾随内容时返回 *LineError。
321	func decodeTopValue(line string) (json.RawMessage, byte, *LineError) {
322		if lerr := validateLineText(line); lerr != nil {
323			return nil, 0, lerr
324		}
325		dec := json.NewDecoder(strings.NewReader(line))
326		var top json.RawMessage
327		if err := dec.Decode(&top); err != nil {
328			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
329		}
330		// 第一个 JSON 值之后只允许输入结束（Decoder 自动跳过尾随空白）。
331		if err := dec.Decode(new(json.RawMessage)); err != io.EOF {
332			if err == nil {
333				err = fmt.Errorf("unexpected content after the JSON value")
334			}
335			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
336		}
337		trimmed := strings.TrimSpace(string(top))
338		if len(trimmed) == 0 || (trimmed[0] != '[' && trimmed[0] != '{') {
339			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
340		}
341		return top, trimmed[0], nil
342	}
343	
344	// fieldReader 从 dec 读取并校验当前字段的值，写入调用方持有的结果。
345	// 采样点与查询对象各自注册自己允许的字段及字段含义。
346	type fieldReader func(dec *json.Decoder) error
347	
348	// parseStrictObject 是写入采样点与查询对象共用的严格对象校验骨架：
349	// 仅允许 fields 中列出的字段（未知字段先于判重被拒绝），同一对象内按转义还原
350	// 后的字段名判重（即使两个值相同也拒绝；判重不跨对象、不跨层级），按输入次序
351	// 逐字段调用对应的 fieldReader，对象结束后要求输入恰好耗尽，最后按 required
352	// 的顺序报告缺失的必填字段。notObjectMsg 与 trailingMsg 由调用方给出，
353	// 保留各自输入的措辞。
354	func parseStrictObject(raw json.RawMessage, notObjectMsg, trailingMsg string, required []string, fields map[string]fieldReader) error {
355		dec := json.NewDecoder(bytes.NewReader(raw))
356		dec.UseNumber()
357	
358		tok, err := dec.Token()
359		if err != nil {
360			return err
361		}
362		if d, ok := tok.(json.Delim); !ok || d != '{' {
363			return fmt.Errorf("%s", notObjectMsg)
364		}
365	
366		present := make(map[string]bool)
367		for dec.More() {
368			keyTok, err := dec.Token()
369			if err != nil {
370				return err
371			}
372			key := keyTok.(string)
373			read, ok := fields[key]
374			if !ok {
375				return fmt.Errorf("unknown field %q", key)
376			}
377			if present[key] {
378				return fmt.Errorf("duplicate field %q", key)
379			}
380			present[key] = true
381			if err := read(dec); err != nil {
382				return err
383			}
384		}
385		if _, err := dec.Token(); err != nil { // 消耗 '}'
386			return err
387		}
388		if _, err := dec.Token(); err != io.EOF {
389			if err == nil {
390				return fmt.Errorf("%s", trailingMsg)
391			}
392			return err
393		}
394	
395		for _, field := range required {
396			if !present[field] {
397				return fmt.Errorf("missing required field %q", field)
398			}
399		}
400		return nil
401	}
402	
403	// readNameField 读取写入与查询共用的指标名字段：必须是非空字符串。
404	func readNameField(dec *json.Decoder, dst *string) error {
405		t, err := dec.Token()
406		if err != nil {
407			return err
408		}
409		s, ok := t.(string)
410		if !ok {
411			return fmt.Errorf(`field "name" must be a string`)
412		}
413		if s == "" {
414			return fmt.Errorf(`field "name" must be a non-empty string`)
415		}
416		*dst = s
417		return nil
418	}
419	
420	// readInt64Field 读取 int64 毫秒整数字段（timestamp/start/end）：
421	// 必须是 JSON 整数且在 int64 范围内，数字字符串、布尔值、带小数点一律拒绝。
422	func readInt64Field(dec *json.Decoder, field string, dst *int64) error {
423		n, err := nextJSONNumber(dec, field)
424		if err != nil {
425			return err
426		}
427		v, err := parseJSONInt(n)
428		if err != nil {
429			return fmt.Errorf("field %q: %s", field, err)
430		}
431		*dst = v
432		return nil
433	}
434	
435	// readFiniteFloatField 读取采样值字段：必须是可表示为有限 float64 的 JSON 数字。
436	func readFiniteFloatField(dec *json.Decoder, field string, dst *float64) error {
437		n, err := nextJSONNumber(dec, field)
438		if err != nil {
439			return err
440		}
441		v, err := parseFiniteFloat(n)
442		if err != nil {
443			return fmt.Errorf("field %q: %s", field, err)
444		}
445		*dst = v
446		return nil
447	}
448	
449	// readLabelsField 读取标签对象字段并写入 dst；notObjectMsg 保留各输入侧措辞。
450	func readLabelsField(dec *json.Decoder, notObjectMsg string, dst *map[string]string) error {
451		labels, err := parseLabels(dec, notObjectMsg)
452		if err != nil {
453			return err
454		}
455		*dst = labels
456		return nil
457	}
458	
459	type parsedSample struct {
460		name   string
461		ts     int64
462		value  float64
463		labels map[string]string
464	}
465	
466	// parseSample 对单个采样点做严格校验：仅允许四个已知字段、拒绝重复键，
467	// 标量必须是精确的 JSON 类型，timestamp 为 int64 整数，value 为有限 float64。
468	func parseSample(raw json.RawMessage) (parsedSample, error) {
469		var p parsedSample
470		p.labels = map[string]string{}
471		err := parseStrictObject(raw,
472			"each sample must be a JSON object",
473			"unexpected content after the sample object",
474			[]string{"name", "timestamp", "value"},
475			map[string]fieldReader{
476				"name":      func(dec *json.Decoder) error { return readNameField(dec, &p.name) },
477				"timestamp": func(dec *json.Decoder) error { return readInt64Field(dec, "timestamp", &p.ts) },
478				"value":     func(dec *json.Decoder) error { return readFiniteFloatField(dec, "value", &p.value) },
479				"labels": func(dec *json.Decoder) error {
480					return readLabelsField(dec, `field "labels" must be an object of string keys to string values`, &p.labels)
481				},
482			})
483		return p, err
484	}
485	
486	// parseLabels 从 dec 读取一个标签对象并做统一校验：必须是 JSON 对象
487	// （否则返回调用方给出的 notObjectMsg，写入与查询措辞不同），键为非空字符串、
488	// 值为字符串（空串合法，键值均不做清理），重复键一律拒绝。
489	// 判重先于值的类型校验：某个键第一次出现时若值不是字符串，仍报告该值的类型
490	// 错误；而该键再次出现时，无论第二次的值是什么（数字、布尔、null、对象、数组），
491	// 都先报告重复标签键，不能让第二次值的类型掩盖键重复。
492	// 返回的集合不含标签时也是非 nil 的空 map，与省略 labels 的语义一致。
493	func parseLabels(dec *json.Decoder, notObjectMsg string) (map[string]string, error) {
494		t, err := dec.Token()
495		if err != nil {
496			return nil, err
497		}
498		d, ok := t.(json.Delim)
499		if !ok || d != '{' {
500			return nil, fmt.Errorf("%s", notObjectMsg)
501		}
502		labels := map[string]string{}
503		for dec.More() {
504			labelKeyTok, err := dec.Token()
505			if err != nil {
506				return nil, err
507			}
508			labelKey := labelKeyTok.(string)
509			if labelKey == "" {
510				return nil, fmt.Errorf(`field "labels": label keys must be non-empty strings`)
511			}
512			// 先判重再读值：与采样点/查询字段的判重一致，重复键不被值的类型掩盖。
513			if _, dup := labels[labelKey]; dup {
514				return nil, fmt.Errorf(`field "labels": duplicate label key %q`, labelKey)
515			}
516			valTok, err := dec.Token()
517			if err != nil {
518				return nil, err
519			}
520			labelVal, ok := valTok.(string)
521			if !ok {
522				return nil, fmt.Errorf(`field "labels": value of label %q must be a string`, labelKey)
523			}
524			labels[labelKey] = labelVal
525		}
526		if _, err := dec.Token(); err != nil { // 消耗 '}'
527			return nil, err
528		}
529		return labels, nil
530	}
531	
532	func nextJSONNumber(dec *json.Decoder, field string) (json.Number, error) {
533		t, err := dec.Token()
534		if err != nil {
535			return "", err
536		}
537		n, ok := t.(json.Number)
538		if !ok {
539			return "", fmt.Errorf(`field %q must be a JSON number`, field)
540		}
541		return n, nil
542	}
543	
544	func parseJSONInt(n json.Number) (int64, error) {
545		s := string(n)
546		if !jsonIntegerRE.MatchString(s) {
547			return 0, fmt.Errorf("must be a JSON integer in milliseconds")
548		}
549		v, err := strconv.ParseInt(s, 10, 64)
550		if err != nil {
551			return 0, fmt.Errorf("must be within int64 range")
552		}
553		return v, nil
554	}
555	
556	func parseFiniteFloat(n json.Number) (float64, error) {
557		s := string(n)
558		if !jsonNumberRE.MatchString(s) {
559			return 0, fmt.Errorf("must be a JSON number")
560		}
561		v, err := strconv.ParseFloat(s, 64)
562		if err != nil || math.IsInf(v, 0) || math.IsNaN(v) {
563			return 0, fmt.Errorf("must be a finite number representable as float64")
564		}
565		return v, nil
566	}
567	
568	// ingestItems 完成全部采样点校验与冲突检测后再统一提交，保证整批原子性。
569	func (s *MetricStore) ingestItems(items []json.RawMessage) (*BatchResult, *LineError) {
570		type pending struct {
571			id  seriesID
572			ref SeriesRef
573			ts  int64
574			val float64
575		}
576	
577		added := 0
578		// 本批已确定身份的点（含与已写入数据重复的点），用于批内去重与冲突检测。
579		seen := make(map[seriesID]map[int64]float64)
580		// 仅记录需要落盘的新增点；校验全部通过后才提交。
581		commits := make([]pending, 0, len(items))
582	
583		failAt := func(index int, msg string) *LineError {
584			return &LineError{Status: "error", Index: index, Error: msg}
585		}
586		conflictAt := func(index int, ref SeriesRef, ts int64, existing, submitted float64) *LineError {
587			return &LineError{
588				Status: "error",
589				Index:  index,
590				Error: fmt.Sprintf("conflict: series %s at timestamp %d already has value %s, submitted %s",
591					ref, ts, formatFloat(existing), formatFloat(submitted)),
592				Conflict: &Conflict{
593					// 标签必须复制：冲突结果是本次失败的独立记录，
594					// 调用方修改它不能改动已存序列的身份。
595					Series:    SeriesRef{Name: ref.Name, Labels: cloneLabels(ref.Labels)},
596					Timestamp: ts,
597					Existing:  existing,
598					Submitted: submitted,
599				},
600			}
601		}
602	
603		for i, item := range items {
604			pos := i + 1
605			p, err := parseSample(item)
606			if err != nil {
607				return nil, failAt(pos, err.Error())
608			}
609	
610			id := makeSeriesID(p.name, p.labels)
611			ref := SeriesRef{Name: p.name, Labels: p.labels}
612	
613			if byTS, ok := seen[id]; ok {
614				if old, ok := byTS[p.ts]; ok {
615					if old != p.value {
616						return nil, conflictAt(pos, ref, p.ts, old, p.value)
617					}
618					// 同批内重复出现且数值相同：重复，成功忽略。
619					continue
620				}
621			}
622			if sr, ok := s.series[id]; ok {
623				if old, ok := sr.points[p.ts]; ok {
624					if old != p.value {
625						return nil, conflictAt(pos, sr.ref, p.ts, old, p.value)
626					}
627					// 与此前批次已写入的值相同：重复，成功忽略。
628					if seen[id] == nil {
629						seen[id] = map[int64]float64{}
630					}
631					seen[id][p.ts] = p.value
632					continue
633				}
634			}
635	
636			added++
637			if seen[id] == nil {
638				seen[id] = map[int64]float64{}
639			}
640			seen[id][p.ts] = p.value
641			commits = append(commits, pending{id: id, ref: ref, ts: p.ts, val: p.value})
642		}
643	
644		// 全部采样点合法且无冲突，原子提交本批新增点。
645		for _, c := range commits {
646			sr := s.series[c.id]
647			if sr == nil {
648				sr = &storedSeries{ref: c.ref, points: map[int64]float64{}}
649				s.series[c.id] = sr
650			}
651			sr.points[c.ts] = c.val
652		}
653	
654		return s.snapshot(added, len(items)-added), nil
655	}
656	
657	// formatFloat 以 JSON 数值风格格式化 float64：1 与 1.0 均显示为 1。
658	func formatFloat(v float64) string {
659		return strconv.FormatFloat(v, 'g', -1, 64)
660	}
661	
662	type parsedQuery struct {
663		name   string
664		start  int64
665		end    int64
666		labels map[string]string
667	}
668	
669	// queryFromObject 严格解析查询对象并执行只读区间均值查询。
670	func (s *MetricStore) queryFromObject(raw json.RawMessage) (*QueryResult, *LineError) {
671		q, err := parseQuery(raw)
672		if err != nil {
673			return nil, &LineError{Status: "error", Error: err.Error()}
674		}
675		if q.start > q.end {
676			return nil, &LineError{Status: "error", Error: fmt.Sprintf(
677				`invalid range: "start" must not be greater than "end" (%d > %d)`, q.start, q.end)}
678		}
679		return s.runQuery(q), nil
680	}
681	
682	// parseQuery 对查询对象做严格校验：仅允许 op/name/start/end/labels，
683	// 拒绝重复键与未知字段；标量必须是精确的 JSON 类型，start/end 为 int64 毫秒。
684	func parseQuery(raw json.RawMessage) (parsedQuery, error) {
685		var q parsedQuery
686		err := parseStrictObject(raw,
687			"each query must be a JSON object",
688			"unexpected content after the query object",
689			[]string{"op", "name", "start", "end"},
690			map[string]fieldReader{
691				"op": func(dec *json.Decoder) error {
692					t, err := dec.Token()
693					if err != nil {
694						return err
695					}
696					op, ok := t.(string)
697					if !ok {
698						return fmt.Errorf(`field "op" must be a string`)
699					}
700					if op != "query" {
701						return fmt.Errorf(`unknown op %q (only "query" is supported)`, op)
702					}
703					return nil
704				},
705				"name":  func(dec *json.Decoder) error { return readNameField(dec, &q.name) },
706				"start": func(dec *json.Decoder) error { return readInt64Field(dec, "start", &q.start) },
707				"end":   func(dec *json.Decoder) error { return readInt64Field(dec, "end", &q.end) },
708				"labels": func(dec *json.Decoder) error {
709					return readLabelsField(dec, `field "labels" must be an object of non-empty string keys to string values`, &q.labels)
710				},
711			})
712		return q, err
713	}
714	
715	// labelsMatch 实现子集匹配：want 中每个键都必须在 stored 中存在且值完全相等，
716	// stored 可以含额外标签；空字符串值只匹配真实存在的空值标签。
717	func labelsMatch(want, stored map[string]string) bool {
718		for k, v := range want {
719			got, ok := stored[k]
720			if !ok || got != v {
721				return false
722			}
723		}
724		return true
725	}
726	
727	// runQuery 只读扫描已成功提交的数据：name 精确、标签子集、[start,end] 闭区间。
728	// 序列次序与写入快照共用 organizeSeries 的整理结果：过滤掉其他序列后，
729	// 保留的序列仍是同一排序中的一个子序列，不另换排序；无区间内点的序列不列出。
730	func (s *MetricStore) runQuery(q parsedQuery) *QueryResult {
731		inRange := func(ts int64) bool { return ts >= q.start && ts <= q.end }
732		out := make([]QuerySeries, 0)
733		for _, os := range s.organizeSeries() {
734			if os.ref.Name != q.name || !labelsMatch(q.labels, os.ref.Labels) {
735				continue
736			}
737			points := sortedSeriesPoints(os.sr, inRange)
738			if len(points) == 0 {
739				continue
740			}
741			values := make([]float64, len(points))
742			for i, p := range points {
743				values[i] = p.Value
744			}
745			out = append(out, QuerySeries{
746				Name:    os.ref.Name,
747				Labels:  os.ref.Labels,
748				Count:   len(values),
749				Average: finiteMean(values),
750			})
751		}
752		return &QueryResult{Status: "ok", Op: "query", Series: out}
753	}
754	
755	// finiteMean 返回已存储 float64 值的精确算术平均所对应的最近 float64，
756	// 恰好在两个相邻可表示值中间时按最近偶数舍入。
757	// 求和用有理数精确完成：与点的顺序、批次划分无关，正负大数抵消后的小余量
758	// 不会丢失，总和超出 float64 范围时结果仍然有限。精确平均为零时返回 +0；
759	// 只有一个点时结果就是该点的值。
760	func finiteMean(values []float64) float64 {
761		sum := new(big.Rat)
762		r := new(big.Rat)
763		for _, v := range values {
764			// 写入侧已保证 v 有限，SetFloat64 对有限值是精确的。
765			sum.Add(sum, r.SetFloat64(v))
766		}
767		sum.Quo(sum, r.SetInt64(int64(len(values))))
768		return ratToFloat64NearestEven(sum)
769	}
770	
771	// ratToFloat64NearestEven 把有理数 x 舍入到最近的 float64，半数取偶。
772	// 调用方保证 |x| 不超过 MaxFloat64（有限值的均值必然满足），因此不会溢出。
773	func ratToFloat64NearestEven(x *big.Rat) float64 {
774		if x.Sign() == 0 {
775			return 0
776		}
777		num := new(big.Int).Set(x.Num())
778		den := x.Denom()
779		neg := num.Sign() < 0
780		if neg {
781			num.Neg(num)
782		}
783	
784		// e 满足 2^e <= num/den < 2^(e+1)。
785		e := floorLog2Rat(num, den)
786		var m *big.Int
787		scale := 0
788		if e >= -1022 {
789			// 正规数：m 为 num/den 按 2^(e-52) 缩放后的 53 位舍入整数。
790			scale = e - 52
791			m = roundScaledRatio(num, den, scale)
792			if m.BitLen() == 54 {
793				// 舍入进位（如 1.111…1 进为 10.0），指数加一。
794				m.Rsh(m, 1)
795				scale++
796			}
797		} else {
798			// 次正规数：有效位间距固定为 2^-1074；m 舍入为 0 时按 IEEE 得到带符号零。
799			scale = -1074
800			m = roundScaledRatio(num, den, scale)
801		}
802		// m < 2^53，可以精确放入 int64 与 float64。
803		f := math.Ldexp(float64(m.Int64()), scale)
804		if neg {
805			return -f
806		}
807		return f
808	}
809	
810	// floorLog2Rat 返回正有理数 num/den 的二进制阶：最大的 e 使 2^e <= num/den。
811	func floorLog2Rat(num, den *big.Int) int {
812		k := num.BitLen() - den.BitLen()
813		var t big.Int
814		if k >= 0 {
815			t.Lsh(den, uint(k))
816			if num.Cmp(&t) >= 0 {
817				return k
818			}
819			return k - 1
820		}
821		t.Lsh(num, uint(-k))
822		if t.Cmp(den) >= 0 {
823			return k
824		}
825		return k - 1
826	}
827	
828	// roundScaledRatio 返回 round(num / (den · 2^scale))，半数取偶；num、den 均为正。
829	func roundScaledRatio(num, den *big.Int, scale int) *big.Int {
830		n := new(big.Int).Set(num)
831		d := new(big.Int).Set(den)
832		if scale >= 0 {
833			d.Lsh(d, uint(scale))
834		} else {
835			n.Lsh(n, uint(-scale))
836		}
837		q, r := new(big.Int).QuoRem(n, d, new(big.Int))
838		switch r2 := new(big.Int).Lsh(r, 1); r2.Cmp(d) {
839		case 1:
840			q.Add(q, big.NewInt(1))
841		case 0:
842			if q.Bit(0) == 1 {
843				q.Add(q, big.NewInt(1))
844			}
845		}
846		return q
847	}
848	
849	// String 让冲突原因中的序列身份可读且无歧义：name{k=v,...}，标签按键排序。
850	// 名称、标签键、标签值是不含分隔字符（逗号、等号、花括号、引号、反斜杠）、
851	// 不含首尾空白与不可打印字符的非空字符串时按原文呈现（cpu{host=a} 保持原样）；
852	// 否则以带引号的字符串字面量呈现，使内容字符与标签边界永远可以区分——
853	// 单标签值 "1,b=2" 渲染为 a="1,b=2"，与两标签 a=1,b=2 不再混淆；换行、
854	// 制表符等呈现为 \n、\t 这样的可辨认文字标记，一条冲突原因始终是一条记录；
855	// 空字符串值渲染为 ""，与无标签的 {} 明确区分。渲染只依赖解析后的真实身份，
856	// 与标签书写顺序、字符是否以 JSON 转义书写无关。
857	func (r SeriesRef) String() string {
858		var b strings.Builder
859		b.WriteString(identityText(r.Name))
860		b.WriteByte('{')
861		for i, p := range sortedPairs(r.Labels) {
862			if i > 0 {
863				b.WriteByte(',')
864			}
865			b.WriteString(identityText(p.Key))
866			b.WriteByte('=')
867			b.WriteString(identityText(p.Value))
868		}
869		b.WriteByte('}')
870		return b.String()
871	}
872	
873	// identityText 把身份组成部分（指标名、标签键、标签值）渲染为无歧义文本：
874	// 不含分隔字符、首尾空白与不可打印字符的非空字符串原样返回；其余情况用
875	// strconv.Quote 加引号并转义，引号边界标出内容的起止（首尾空格、空串可见），
876	// 控制字符呈现为 \n、\t 等转义标记。分隔字符与引号、反斜杠一律被引号包裹，
877	// 因此渲染结果不会把内容字符误读为标签边界。
878	func identityText(s string) string {
879		if s == "" || s != strings.TrimSpace(s) {
880			return strconv.Quote(s)
881		}
882		for _, r := range s {
883			if !unicode.IsPrint(r) || strings.ContainsRune(`,={}"\`, r) {
884				return strconv.Quote(s)
885			}
886		}
887		return s
888	}
889	
890	// organizedSeries 是一次结果整理中的一条序列：携带已存序列指针、
891	// 供结果直接使用的独立标签副本（标签书写顺序不影响身份，
892	// 副本使调用方对结果的修改不能回写存储），以及该副本按键升序
893	// 整理好的键值对，供排序比较直接复用。
894	type organizedSeries struct {
895		sr    *storedSeries
896		ref   SeriesRef
897		pairs []labelPair
898	}
899	
900	// organizeSeries 是写入快照与区间查询共用的数据整理逻辑：
901	// 遍历全部已提交序列，复制各自的序列身份，并按唯一的顺序约定排列——
902	// 先按指标名字符串字典序，再按标签键升序后的键值对逐对比较
903	// （先比键再比值，前一对相同才比下一对；较短集合是完整前缀时排前，
904	// 无标签序列因此排在最前）。标签值按字符串比较（"10" 在 "2" 之前）。
905	// 每条序列的标签只在遍历时整理一次：排序后的键值对随条目保留，
906	// sort 的反复比较直接复用同一份结果，不会因一条序列参与多次比较
907	// 而反复整理同一套标签。整理结果不复制采样点；采样点的选取与升序
908	// 排列由 sortedSeriesPoints 完成。
909	func (s *MetricStore) organizeSeries() []organizedSeries {
910		out := make([]organizedSeries, 0, len(s.series))
911		for _, sr := range s.series {
912			// 标签必须复制：成功结果是当次操作的独立记录，
913			// 调用方修改结果标签不能改动已存序列的身份。
914			labels := cloneLabels(sr.ref.Labels)
915			out = append(out, organizedSeries{
916				sr:    sr,
917				ref:   SeriesRef{Name: sr.ref.Name, Labels: labels},
918				pairs: sortedPairs(labels),
919			})
920		}
921		sort.Slice(out, func(i, j int) bool {
922			if out[i].ref.Name != out[j].ref.Name {
923				return out[i].ref.Name < out[j].ref.Name
924			}
925			return compareLabelPairs(out[i].pairs, out[j].pairs) < 0
926		})
927		return out
928	}
929	
930	// sortedSeriesPoints 按 timestamp 升序返回一条已存序列中满足 keep 的采样点，
931	// 数值与时间戳一一对应。keep 为 nil 时返回全部点（写入快照）；
932	// 区间查询传入闭区间判定，查询只选取区间内的点。
933	// 返回的是新建切片与新建 Point，调用方对采样点的修改不影响存储，
934	// 也不影响此前或此后取得的其他成功结果。
935	func sortedSeriesPoints(sr *storedSeries, keep func(ts int64) bool) []Point {
936		tsList := make([]int64, 0, len(sr.points))
937		for ts := range sr.points {
938			if keep == nil || keep(ts) {
939				tsList = append(tsList, ts)
940			}
941		}
942		sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
943		points := make([]Point, len(tsList))
944		for i, ts := range tsList {
945			points[i] = Point{Timestamp: ts, Value: sr.points[ts]}
946		}
947		return points
948	}
949	
950	// snapshot 生成按规范排序的全部序列视图：序列次序与点排列均来自
951	// organizeSeries/sortedSeriesPoints 这套与查询共用的整理逻辑。
952	func (s *MetricStore) snapshot(added, duplicates int) *BatchResult {
953		organized := s.organizeSeries()
954		views := make([]SeriesView, 0, len(organized))
955		for _, os := range organized {
956			views = append(views, SeriesView{
957				Name:   os.ref.Name,
958				Labels: os.ref.Labels,
959				Points: sortedSeriesPoints(os.sr, nil),
960			})
961		}
962		return &BatchResult{Status: "ok", Added: added, Duplicates: duplicates, Series: views}
963	}
964

