135			res := mustOK(t, store, sampleLineZero(1000, spelling))
136			if res.Added != 0 || res.Duplicates != 1 {
137				t.Fatalf("%s against stored +0 counts = %d/%d, want 0/1",
138					spelling, res.Added, res.Duplicates)
139			}
140			p := res.Series[0].Points[0]
141			if p.Value != 0 || math.Signbit(p.Value) {
142				t.Fatalf("%s must not overwrite stored +0, got point %+v", spelling, p)
143			}
144		}
145	
146		// 相反顺序：先存由 -1e-400 舍入成的负零，再提交正零文本与舍入成正零的
147		// 1e-400，同样全部忽略，存储保持负零。
148		store2 := NewMetricStore()
149		mustOK(t, store2, sampleLineZero(1000, "-1e-400"))
150		for _, spelling := range []string{"0", "0.0", "1e-400"} {
151			res := mustOK(t, store2, sampleLineZero(1000, spelling))
152			if res.Added != 0 || res.Duplicates != 1 {
153				t.Fatalf("%s against stored -0 counts = %d/%d, want 0/1",
154					spelling, res.Added, res.Duplicates)
155			}
156			p := res.Series[0].Points[0]
157			if p.Value != 0 || !math.Signbit(p.Value) {
158				t.Fatalf("%s must not overwrite stored -0, got point %+v", spelling, p)
159			}
160		}
161	
162		// 同一批内、此前没有该位置：1e-400 先出现则存正零，-1e-400 与 -0 是重复；
163		// 调换先后则存负零。
164		store3 := NewMetricStore()
165		res := mustOK(t, store3, `[
166			{"name":"m","timestamp":1,"value":1e-400},
167			{"name":"m","timestamp":1,"value":-1e-400},
168			{"name":"m","timestamp":1,"value":-0}
169		]`)
170		if res.Added != 1 || res.Duplicates != 2 {
171			t.Fatalf("rounded-to-zero within-batch counts = %d/%d, want 1/2", res.Added, res.Duplicates)
172		}
173		if p := res.Series[0].Points[0]; p.Value != 0 || math.Signbit(p.Value) {
174			t.Fatalf("first 1e-400 must be stored as +0, got %+v", p)
175		}
176	
177		store4 := NewMetricStore()
178		res = mustOK(t, store4, `[
179			{"name":"m","timestamp":1,"value":-1e-400},
180			{"name":"m","timestamp":1,"value":1e-400}
181		]`)
182		if res.Added != 1 || res.Duplicates != 1 {
183			t.Fatalf("reversed within-batch counts = %d/%d, want 1/1", res.Added, res.Duplicates)
184		}
185		if p := res.Series[0].Points[0]; p.Value != 0 || !math.Signbit(p.Value) {
186			t.Fatalf("first -1e-400 must be stored as -0, got %+v", p)
187		}
188	}
189	
190	// TestZeroDedupSubnormalConflictsWithZero 确认 5e-324 仍是可区分的非零值：
191	// 已存零（正零或负零）后向同一位置提交它必须冲突，整批拒绝——本批前面的
192	// 合法新增点不提交，冲突信息给出序列、时间戳、判定冲突时的零值（保留已存
193	// 符号）与提交的极小值，原有的零也不能被替换。反向提交（先存 5e-324 再
194	// 提交零）同样冲突。
195	func TestZeroDedupSubnormalConflictsWithZero(t *testing.T) {
196		for _, zero := range []struct {
197			spelling string
198			neg      bool
199		}{{"0", false}, {"-0.0", true}} {
200			store := NewMetricStore()
201			mustOK(t, store, sampleLineZero(1000, zero.spelling))
202	
203			// 第一个点是合法新增（ts=2000），第二个点才是冲突：整批拒绝。
204			lerr := mustFail(t, store, `[
205				{"name":"m","timestamp":2000,"value":1},
206				{"name":"m","timestamp":1000,"value":5e-324}
207			]`)
208			if lerr.Index != 2 || lerr.Conflict == nil {
209				t.Fatalf("stored %s: expected conflict at index 2, got %+v", zero.spelling, lerr)
210			}
211			c := lerr.Conflict
212			if c.Series.Name != "m" || len(c.Series.Labels) != 0 || c.Timestamp != 1000 {
213				t.Fatalf("stored %s: conflict identity = %+v, want m{} ts=1000", zero.spelling, c)
214			}
215			if c.Existing != 0 || math.Signbit(c.Existing) != zero.neg {
216				t.Fatalf("stored %s: existing = %v (neg=%v), want the stored zero with neg=%v",
217					zero.spelling, c.Existing, math.Signbit(c.Existing), zero.neg)
218			}
219			if c.Submitted != 5e-324 {
220				t.Fatalf("stored %s: submitted = %v, want 5e-324", zero.spelling, c.Submitted)
221			}
222			wantZeroText := "0"
223			if zero.neg {
224				wantZeroText = "-0"
225			}
226			if !strings.Contains(lerr.Error, "already has value "+wantZeroText) ||
227				!strings.Contains(lerr.Error, "submitted 5e-324") {
228				t.Fatalf("stored %s: error must name %s and 5e-324, got %q",
229					zero.spelling, wantZeroText, lerr.Error)
230			}
231	
232			// 整批回滚：ts=2000 的新增点不留下，ts=1000 的零点（含符号）不被替换。
233			q := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":3000}`)
234			if len(q.Series) != 1 || q.Series[0].Count != 1 || q.Series[0].Average != 0 {
235				t.Fatalf("stored %s: query after conflict = %+v, want only the original zero point",
236					zero.spelling, q.Series)
237			}
238			res := mustOK(t, store, `[]`)
239			p := res.Series[0].Points[0]
240			if p.Value != 0 || math.Signbit(p.Value) != zero.neg {
241				t.Fatalf("stored %s: original zero sign changed after conflict, got %+v",
242					zero.spelling, p)
243			}
244		}
245	
246		// 反向：先存 5e-324，再提交零也必须冲突，existing 是极小值、submitted 是零。
247		store := NewMetricStore()
248		mustOK(t, store, sampleLineZero(1, "5e-324"))
249		lerr := mustFail(t, store, sampleLineZero(1, "0"))
250		if lerr.Index != 1 || lerr.Conflict == nil {
251			t.Fatalf("reverse direction expected conflict at index 1, got %+v", lerr)
252		}
253		if lerr.Conflict.Existing != 5e-324 || lerr.Conflict.Submitted != 0 ||
254			math.Signbit(lerr.Conflict.Submitted) {
255			t.Fatalf("reverse conflict = %+v, want existing=5e-324 submitted=+0", lerr.Conflict)
256		}
257	}
258	
259	// TestZeroDedupDistinctTimestampsAndZeroAverages 覆盖写入后的区间查询：
260	// 同一位置被忽略的重复不增加 count；零值出现在不同时间戳时是不同采样点，
261	// 每个已成功提交的点都参与计数；精确均值为零（含正负零混合、+1/-1 抵消）
262	// 时 average 一律输出正零。
263	func TestZeroDedupDistinctTimestampsAndZeroAverages(t *testing.T) {
264		store := NewMetricStore()
265		// 三个不同时间戳各写一个零（写法、符号各不相同）：都是新增点。
266		res := mustOK(t, store, `[
267			{"name":"m","timestamp":1,"value":0},
268			{"name":"m","timestamp":2,"value":-0.0},
269			{"name":"m","timestamp":3,"value":1e-400}
270		]`)
271		if res.Added != 3 || res.Duplicates != 0 || len(res.Series[0].Points) != 3 {
272			t.Fatalf("zeros at distinct timestamps = %+v, want 3 added points", res)
273		}
274		// 同一位置的重复（含舍入成相反符号零的文本）被忽略，不增加 count。
275		res = mustOK(t, store, `[
276			{"name":"m","timestamp":1,"value":-1e-400},
277			{"name":"m","timestamp":2,"value":0.0}
278		]`)
279		if res.Added != 0 || res.Duplicates != 2 {
280			t.Fatalf("duplicate zeros counts = %d/%d, want 0/2", res.Added, res.Duplicates)
281		}
282	
283		q := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":10}`)
284		if len(q.Series) != 1 || q.Series[0].Count != 3 {
285			t.Fatalf("zero query = %+v, want count=3", q.Series)
286		}
287		if q.Series[0].Average != 0 || math.Signbit(q.Series[0].Average) {
288			t.Fatalf("zero query average = %v, want +0", q.Series[0].Average)
289		}
290	
291		// 非零数据精确抵消成零时，average 同样是正零而不是负零。
292		store2 := NewMetricStore()
293		mustOK(t, store2, `[
294			{"name":"n","timestamp":1,"value":1},
295			{"name":"n","timestamp":2,"value":-1}
296		]`)
297		q2 := mustQuery(t, store2, `{"op":"query","name":"n","start":0,"end":10}`)
298		if len(q2.Series) != 1 || q2.Series[0].Count != 2 ||
299			q2.Series[0].Average != 0 || math.Signbit(q2.Series[0].Average) {
300			t.Fatalf("canceling average = %+v, want count=2 average=+0", q2.Series)
301		}
302	}
